package com.ftk.tpip.control.api.integration;

import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.*;import com.ftk.tpip.control.application.integration.PolicyTypeApplicationService;import com.ftk.tpip.integration.domain.model.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.net.URI;import java.time.Instant;import java.util.*;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/control/v1/policy-types") public class PolicyTypeController{private final PolicyTypeApplicationService service;private final ObjectMapper json;public PolicyTypeController(PolicyTypeApplicationService s,ObjectMapper j){service=s;json=j;}
@PostMapping public ResponseEntity<Response>register(@Valid@RequestBody Register r,@RequestHeader("X-Operator")@NotBlank@Size(max=100)String actor){var x=service.register(r.policyTypeCode,r.semanticVersion,r.implementationKind,r.allowedStages,r.configurationSchema,r.runtimeCompatibility,r.securityClassification,r.deterministic,r.sideEffect,r.idempotencyRequirement,r.implementationRef,r.artifactChecksum,actor);return ResponseEntity.created(URI.create("/control/v1/policy-types/"+x.id())).body(response(x));}@GetMapping("/{id}")public Response get(@PathVariable@Min(1)long id){return response(service.get(id));}@GetMapping public List<Response>list(@RequestParam(defaultValue="false")boolean activeOnly){return service.list(activeOnly).stream().map(this::response).toList();}@PostMapping("/{id}:status")public Response status(@PathVariable@Min(1)long id,@Valid@RequestBody Status r,@RequestHeader("X-Operator")@NotBlank@Size(max=100)String actor){return response(service.status(id,r.status,actor));}
private Response response(PolicyTypeDefinition x){return new Response(x.id(),x.policyTypeCode().value(),x.semanticVersion().toString(),x.implementationKind(),x.allowedStages(),read(x.configurationSchema()),x.runtimeCompatibility(),x.securityClassification(),x.deterministic(),x.sideEffect(),x.idempotencyRequirement(),x.implementationRef(),x.artifactChecksum(),x.status(),x.createdAt());}private JsonNode read(String v){try{return json.readTree(v);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}
public record Register(@NotBlank@Size(max=160)@Pattern(regexp="^[a-z][a-z0-9]*(?:[._-][a-z0-9]+)*$")String policyTypeCode,@NotBlank@Size(max=32)@Pattern(regexp="^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)$")String semanticVersion,@NotNull PolicyImplementationKind implementationKind,@NotEmpty Set<PolicyMountStage>allowedStages,@NotNull JsonNode configurationSchema,@NotBlank@Size(max=100)String runtimeCompatibility,@NotNull PolicySecurityClassification securityClassification,boolean deterministic,boolean sideEffect,PolicyIdempotencyRequirement idempotencyRequirement,@Size(max=500)String implementationRef,@Pattern(regexp="^[a-f0-9]{64}$")String artifactChecksum){}public record Status(@NotNull PolicyTypeStatus status){}public record Response(long id,String policyTypeCode,String semanticVersion,PolicyImplementationKind implementationKind,Set<PolicyMountStage>allowedStages,JsonNode configurationSchema,String runtimeCompatibility,PolicySecurityClassification securityClassification,boolean deterministic,boolean sideEffect,PolicyIdempotencyRequirement idempotencyRequirement,String implementationRef,String artifactChecksum,PolicyTypeStatus status,Instant createdAt){}
}
